  ExitCodeCheck $?

  if [[ -f ${RTKBASE_PATH}/${SYSCONGIG_OLD} ]]; then
     #echo rm ${RTKBASE_PATH}/${SYSCONGIG_OLD}
     rm ${RTKBASE_PATH}/${SYSCONGIG_OLD}
     ExitCodeCheck $?
