        ExitCodeCheck $?
     fi
  fi
  if [[ -f ${SERVICE_PATH}/${SYSSERVICE_OLD} ]]; then
     #echo rm ${SERVICE_PATH}/${SYSSERVICE_OLD}
     rm ${SERVICE_PATH}/${SYSSERVICE_OLD}
