  ExitCodeCheck $?

  if [[ "${BASEDIR}" != "${RTKBASE_PATH}" ]]; then
     #echo mv ${BASEDIR}/${CHECK_INTERNET} ${RTKBASE_PATH}/
     mv ${BASEDIR}/${CHECK_INTERNET} ${RTKBASE_PATH}/
     ExitCodeCheck $?
  fi
  #echo chmod +x ${RTKBASE_PATH}/${CHECK_INTERNET}
