patch_one(){
   #echo patch -f ${1} ${BASEDIR}/${2}
   patch -f ${1} ${BASEDIR}/${2}
   ExitCodeCheck $?
   if [[ -n "${3}" ]]; then
      chmod ${3} ${1}
      ExitCodeCheck $?
   fi
   rm -f ${BASEDIR}/${2}
   ExitCodeCheck $?
}

patch_rtkbase(){
   echo '################################'
   echo 'PATCH RTKBASE'
   echo '################################'

   #echo mv ${BASEDIR}/${NTRIP_C} ${RTKBASE_UNIT}
   mv ${BASEDIR}/${NTRIP_C} ${RTKBASE_UNIT}
   ExitCodeCheck $?
   #echo mv ${BASEDIR}/${NTRIP_D} ${RTKBASE_UNIT}
   mv ${BASEDIR}/${NTRIP_D} ${RTKBASE_UNIT}
   ExitCodeCheck $?
   #echo mv ${BASEDIR}/${NTRIP_E} ${RTKBASE_UNIT}
   mv ${BASEDIR}/${NTRIP_E} ${RTKBASE_UNIT}
   ExitCodeCheck $?

   for file in ${RTKBASE_UNIT}/str2str*; do
      #echo sudo -u "${RTKBASE_USER}" sed -i s/^LogRateLimitBurst=.*/LogRateLimitBurst=100/ "${file}"
      sudo -u "${RTKBASE_USER}" sed -i s/^LogRateLimitBurst=.*/LogRateLimitBurst=100/ "${file}"
      ExitCodeCheck $?
      #echo sudo -u "${RTKBASE_USER}" sed -i s/^Type=simple.*/Type=forking/ "${file}"
      sudo -u "${RTKBASE_USER}" sed -i s/^Type=simple.*/Type=forking/ "${file}"
      ExitCodeCheck $?
   done

   patch_one ${RTKBASE_UNIT}/str2str_tcp.service      ${STR2STR_TCP_PATCH}
   patch_one ${RTKBASE_UNIT}/str2str_ntrip_A.service  ${STR2STR_NTRIP_A_PATCH}
   patch_one ${RTKBASE_UNIT}/str2str_rtcm_svr.service ${STR2STR_RTCM_SVR_PATCH}
   patch_one ${RTKBASE_WEB}/server.py                 ${SERVER_PATCH}
   patch_one ${RTKBASE_WEB}/gnss_rproxy_server.py     ${GNSS_RPROXY_PATCH}
   patch_one ${RTKBASE_WEB}/RTKBaseConfigManager.py   ${RTKBASE_CONFIG_MANAGER_PATCH}
   patch_one ${RTKBASE_WEB}/RtkController.py          ${RTKCONTROLLER_PATCH}
   patch_one ${RTKBASE_WEB}/network_infos.py          ${NETWORK_INFOS_PATCH}
   patch_one ${RTKBASE_WEB}/LogManager.py             ${LOGMANAGER_PATCH}
   patch_one ${RTKBASE_WEB}/static/status.js          ${STATUS_PATCH}
   patch_one ${RTKBASE_WEB}/static/settings.js        ${SETTING_PATCH}
   patch_one ${RTKBASE_WEB}/templates/settings.html   ${SETTING_HTML_PATCH}
   patch_one ${RTKBASE_WEB}/templates/base.html       ${BASE_PATCH}
   patch_one ${RTKBASE_WEB}/server.py                 ${SERVER_NETWORK_PATCH}
   patch_one ${RTKBASE_WEB}/templates/base.html       ${BASE_NETWORK_PATCH}
   patch_one ${RTKBASE_WEB}/rtklib_configs/rtkbase_ppp-static_default.conf ${PPP_CONF_PATCH}
   patch_one ${RTKBASE_TOOLS}/gps/ubx.py              ${UBX_PY_PATCH}
   patch_one ${RTKBASE_TOOLS}/raw2nmea/raw2nmea.sh    ${RAW2NMEA_SH_PATCH}
   patch_one ${OPIZERO_TEMP}                          ${OPIZERO_TEMP_PATCH}           755
   patch_one ${SETTINGS_DEFAULT}                      ${SETTINGS_CONF_PATCH}
   patch_one ${RTKBASE_GIT}/run_cast.sh               ${RUNCAST_PATCH}                755

   sync
   ExitCodeCheck $?
}

wait_apt(){
   # EVONETRTKBASE: aspetta che finisca un apt/dpkg gia' in corso (es. aggiornamenti automatici), max 10 minuti
   for i in $(seq 1 120); do
      pgrep -x "apt-get|apt|dpkg|unattended-upgr" >/dev/null || return 0
      [[ $i == 1 ]] && echo "apt o dpkg occupato da un altro processo: attendo"
      sleep 5
   done
}

rtkbase_install(){
   # EVONETRTKBASE: se "-j -d" fallisce (dipendenze: apt occupato o senza rete) il RTKBase incluso NON viene
   # scompattato e le patch verrebbero riapplicate ai file gia' modificati, rompendo server.py (07/10).
   # Si riprova una volta; se fallisce ancora l'aggiornamento si ferma qui e i file restano intatti.
   for attempt in 1 2; do
      wait_apt
      #echo ${RTKBASE_PATH}/${RTKBASE_INSTALL} -u ${RTKBASE_USER} -j -d
      ${RTKBASE_PATH}/${RTKBASE_INSTALL} -u ${RTKBASE_USER} -j -d 2>&1
      lastcode=$?
      [[ $lastcode == 0 ]] && break
      echo BUG: ${RTKBASE_INSTALL} -j -d finished with exitcode = $lastcode
      [[ $attempt == 1 ]] && echo "Riprovo tra 30 secondi" && sleep 30
   done
   if [[ $lastcode != 0 ]]; then
      echo "ERRORE: installazione di RTKBase non riuscita: aggiornamento ANNULLATO, resta la versione precedente"
      [[ -n "${OLD_VERSION}" ]] && echo ${OLD_VERSION} >${RTKBASE_PATH}/${VERSION_FILE}
      have_receiver && start_rtkbase_services
      delete_all_extracted
      exit 1
   fi

   patch_rtkbase

   #echo ${RTKBASE_PATH}/${RTKBASE_INSTALL} -u ${RTKBASE_USER} -t -g
   ${RTKBASE_PATH}/${RTKBASE_INSTALL} -u ${RTKBASE_USER} -t -g -z 2>&1
   ExitCodeCheck $?
   if [ $lastcode != 0 ]
   then
      echo BUG: ${RTKBASE_INSTALL} -t -g -z finished with exitcode = $lastcode
      #ls -la ${RTKBASE_PATH}/${RTKBASE_INSTALL}
   fi

   #echo rm -f ${RTKBASE_PATH}/${RTKBASE_INSTALL}
   rm -f ${RTKBASE_PATH}/${RTKBASE_INSTALL}
   #echo chown -R ${RTKBASE_USER}:${RTKBASE_USER} ${RTKBASE_GIT}
   #chown -R ${RTKBASE_USER}:${RTKBASE_USER} ${RTKBASE_GIT}
   #ExitCodeCheck $?
}

restart_rtkbase_if_started(){
   if [[ "${ONLINE_UPDATE}" != "UPDATE" ]]; then
      if ! ischroot; then
         if systemctl is-active --quiet rtkbase_web.service; then
            #echo systemctl daemon-reload
            systemctl daemon-reload
            ExitCodeCheck $?
            #echo sudo systemctl restart rtkbase_web.service
            sudo systemctl restart rtkbase_web.service
            ExitCodeCheck $?
         fi
      fi
   fi
}

rename_net_device(){
   OLD_DEVICE_ETH="${1}"
   NEW_DEVICE_ETH="${2}"
   if systemctl is-enabled --quiet NetworkManager.service 2>/dev/null; then
      UUID=`nmcli --fields UUID,DEVICE con show | grep "${OLD_DEVICE_ETH}" | awk -F ' ' '{print $1}'`
      if [[ "${UUID}" != "" ]]; then
         #echo nmcli connection delete uuid "${UUID}"
         nmcli connection delete uuid "${UUID}"
         ExitCodeCheck $?
      fi
   fi
   #echo ip link set ${OLD_DEVICE_ETH} down
   ip link set ${OLD_DEVICE_ETH} down
   ExitCodeCheck $?
   #echo ip link set ${OLD_DEVICE_ETH} name ${NEW_DEVICE_ETH}
   ip link set ${OLD_DEVICE_ETH} name ${NEW_DEVICE_ETH}
   ExitCodeCheck $?
   #echo ip link set ${NEW_DEVICE_ETH} up
   ip link set ${NEW_DEVICE_ETH} up
   ExitCodeCheck $?
   if systemctl is-enabled --quiet NetworkManager.service 2>/dev/null; then
      #echo nmcli device up ${NEW_DEVICE_ETH}
      nmcli device up ${NEW_DEVICE_ETH}
      ExitCodeCheck $?
   fi
   #echo exitcode=$exitcode
}

configure_for_septentrio(){
   if [[ ! -f ${LINK_RULES}/${SEPTENTRIO_LINK} ]]; then
      NEW_MOSAIC_ETH=septentrio
      OLD_MOSAIC_ETH=$(ip route | grep 192.168.3.0 | awk -F ' ' '{print $3}')
      HAVE_MOSAIC=`find -P /dev/serial/by-id -name "*Septentrio*" 2>/dev/null`
      #echo OLD_MOSAIC_ETH=${OLD_MOSAIC_ETH} NEW_MOSAIC_ETH=${NEW_MOSAIC_ETH} HAVE_MOSAI=${HAVE_MOSAIC}
      if [[ "${HAVE_MOSAIC}" != "" ]] && [[ "${OLD_MOSAIC_ETH}" != "" ]] && [[ "${OLD_MOSAIC_ETH}" != "${NEW_MOSAIC_ETH}" ]]; then
         echo '################################'
         echo 'CONFIGURE USB-ETH FOR SEPTENTRIO'
         echo '################################'
         rename_net_device "${OLD_MOSAIC_ETH}" "${NEW_MOSAIC_ETH}"
      fi
   fi
}

configure_for_mobile(){
   if [[ ! -f ${LINK_RULES}/${MOBILE_LINK} ]]; then
      NEW_MOBILE_ETH=mobile
      for productpath in $(find /sys/bus/usb/devices/usb*/ -name product); do
          product=`cat "${productpath}"`
          if [[ "${product}" == "Mobile" ]]; then
             syspath=$(dirname "${productpath}")
             netpath=`find "${syspath}" -name net -type d | head -n 1`
             ethpath=`find "${netpath}" -name eth* -type d | head -n 1`
             OLD_MOBILE_ETH=$(basename "${ethpath}")
             #echo ethpath="${ethpath}" OLD_MOBILE_ETH=${OLD_MOBILE_ETH}
             break
          fi
      done
      #echo OLD_MOBILE_ETH=${OLD_MOBILE_ETH} NEW_MOBILE_ETH=${NEW_MOBILE_ETH}
      if [[ "${OLD_MOBILE_ETH}" != "" ]] && [[ "${OLD_MOBILE_ETH}" != "${NEW_MOBILE_ETH}" ]]; then
         echo '################################'
         echo 'CONFIGURE USB-ETH FOR MOBILE'
         echo '################################'
         rename_net_device "${OLD_MOBILE_ETH}" "${NEW_MOBILE_ETH}"
      fi
   fi
}

